mapper.select:
SELECT * FROM Inquiry 
    WHERE id = #{id}
    ORDER BY i_idx DESC;

mapper.update:
UPDATE Inquiry
    SET i_subject = #{i_subject},
        i_content = #{i_content}
    WHERE i_idx = #{i_idx};

UPDATE Inquiry
    SET i_active = 1
    WHERE idx = #{i_idx};

UPDATE User_t
    SET name = #{name},
        phonenumber = #{phonenumber},
        email = #{email}
    WHERE u_idx = #{u_idx};

UPDATE Add_profile
    SET p_job = #{p_job},
        p_class = #{p_class},
        p_career = #{p_career},
        p_location = #{p_location}
    WHERE u_idx = #{u_idx};

mapper.select:
SELECT *
    FROM Calender_t
    WHERE u_idx = #{u_idx} AND c_active = 1;

mapper.update:
UPDATE Calender_t
    SET title = #{title},
        start = #{start},
        end = #{end}
    WHERE c_idx = #{c_idx};

UPDATE Calender_t
    SET c_active = 0
    WHERE c_idx = #{c_idx};
